// Line Monitor for iPhone (Scriptable). Pure Telecom VDSL line stats and drops,
// read straight from the Pure box over home Wi-Fi. No server needed.
// https://github.com/YabbaYabbaYabba/pure-line-monitor
//
// The box's password is kept in the iPhone Keychain, never in this file.
// Be gentle with the box: one login per read with a proper logout, at most one read a
// minute, a pause after any error, and no log download (it upset the box's web page).

const VERSION = "1.0.0";
const DEFAULTS = { host: "192.168.1.254", user: "admin" };
const KC = { pass: "pure-line-monitor.password", host: "pure-line-monitor.host", user: "pure-line-monitor.user" };
const MIN_READ_GAP = 60;          // seconds between real reads of the box
const BACKOFF = [600, 1200, 1800]; // pause after 1, 2, 3+ errors in a row
const RESYNC_GAP = 90;             // a sync time this much later = the line re-synced
const KEEP_DAYS = 30;
const MAX_SAMPLES = 3000;

// ---------------------------------------------------------------- hashing
// The Pure box hashes the login with MD5 or SHA-512. Scriptable has no crypto
// library, so both are implemented here. SHA-512 constants are derived at start-up
// (cube/square roots of primes) rather than typed in, so there are no typos.

function utf8Bytes(str) {
  const s = unescape(encodeURIComponent(str));
  const out = new Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

function md5(str) {
  const bytes = utf8Bytes(str);
  const T = [];
  for (let i = 0; i < 64; i++) T[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) >>> 0;
  const S = [7, 12, 17, 22, 5, 9, 14, 20, 4, 11, 16, 23, 6, 10, 15, 21];
  const len = bytes.length;
  const msg = bytes.slice();
  msg.push(0x80);
  while (msg.length % 64 !== 56) msg.push(0);
  const bits = len * 8;
  for (let i = 0; i < 8; i++) msg.push(i < 4 ? (bits >>> (8 * i)) & 0xff : Math.floor(bits / 2 ** (8 * i)) & 0xff);
  let a0 = 0x67452301, b0 = 0xefcdab89, c0 = 0x98badcfe, d0 = 0x10325476;
  for (let off = 0; off < msg.length; off += 64) {
    const M = [];
    for (let i = 0; i < 16; i++) {
      const j = off + i * 4;
      M[i] = (msg[j] | (msg[j + 1] << 8) | (msg[j + 2] << 16) | (msg[j + 3] << 24)) >>> 0;
    }
    let A = a0, B = b0, C = c0, D = d0;
    for (let i = 0; i < 64; i++) {
      let F, g;
      if (i < 16) { F = (B & C) | (~B & D); g = i; }
      else if (i < 32) { F = (D & B) | (~D & C); g = (5 * i + 1) % 16; }
      else if (i < 48) { F = B ^ C ^ D; g = (3 * i + 5) % 16; }
      else { F = C ^ (B | ~D); g = (7 * i) % 16; }
      const s = S[(i >> 4) * 4 + (i % 4)];
      const tmp = D;
      D = C;
      C = B;
      const sum = (A + F + T[i] + M[g]) >>> 0;
      B = (B + ((sum << s) | (sum >>> (32 - s)))) >>> 0;
      A = tmp;
    }
    a0 = (a0 + A) >>> 0; b0 = (b0 + B) >>> 0; c0 = (c0 + C) >>> 0; d0 = (d0 + D) >>> 0;
  }
  let hex = "";
  for (const w of [a0, b0, c0, d0]) for (let i = 0; i < 4; i++) hex += ((w >>> (8 * i)) & 0xff).toString(16).padStart(2, "0");
  return hex;
}

const SHA512 = (() => {
  const MASK = (1n << 64n) - 1n;
  const primes = [];
  for (let n = 2; primes.length < 80; n++) if (primes.every((p) => n % p)) primes.push(n);
  const iroot = (v, k) => { // integer k-th root by Newton's method
    let x = 1n << BigInt(Math.ceil(v.toString(2).length / k) + 1);
    for (;;) {
      const y = ((BigInt(k) - 1n) * x + v / x ** (BigInt(k) - 1n)) / BigInt(k);
      if (y >= x) return x;
      x = y;
    }
  };
  const K = primes.map((p) => iroot(BigInt(p) << 192n, 3) & MASK);
  const H = primes.slice(0, 8).map((p) => iroot(BigInt(p) << 128n, 2) & MASK);
  const rotr = (x, n) => ((x >> n) | (x << (64n - n))) & MASK;
  return { K, H, MASK, rotr };
})();

function sha512(str) {
  const { K, H, MASK, rotr } = SHA512;
  const bytes = utf8Bytes(str);
  const len = bytes.length;
  const msg = bytes.slice();
  msg.push(0x80);
  while (msg.length % 128 !== 112) msg.push(0);
  const bitLen = BigInt(len) * 8n;
  for (let i = 15; i >= 0; i--) msg.push(Number((bitLen >> BigInt(8 * i)) & 0xffn));
  const h = H.slice();
  for (let off = 0; off < msg.length; off += 128) {
    const W = new Array(80);
    for (let i = 0; i < 16; i++) {
      let w = 0n;
      for (let j = 0; j < 8; j++) w = (w << 8n) | BigInt(msg[off + i * 8 + j]);
      W[i] = w;
    }
    for (let i = 16; i < 80; i++) {
      const s0 = rotr(W[i - 15], 1n) ^ rotr(W[i - 15], 8n) ^ (W[i - 15] >> 7n);
      const s1 = rotr(W[i - 2], 19n) ^ rotr(W[i - 2], 61n) ^ (W[i - 2] >> 6n);
      W[i] = (W[i - 16] + s0 + W[i - 7] + s1) & MASK;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let i = 0; i < 80; i++) {
      const S1 = rotr(e, 14n) ^ rotr(e, 18n) ^ rotr(e, 41n);
      const ch = (e & f) ^ (~e & MASK & g);
      const t1 = (hh + S1 + ch + K[i] + W[i]) & MASK;
      const S0 = rotr(a, 28n) ^ rotr(a, 34n) ^ rotr(a, 39n);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) & MASK;
      hh = g; g = f; f = e; e = (d + t1) & MASK; d = c; c = b; b = a; a = (t1 + t2) & MASK;
    }
    const v = [a, b, c, d, e, f, g, hh];
    for (let i = 0; i < 8; i++) h[i] = (h[i] + v[i]) & MASK;
  }
  return h.map((x) => x.toString(16).padStart(16, "0")).join("");
}

// ---------------------------------------------------------------- settings

function kcGet(k, dflt) {
  try { return Keychain.contains(k) ? Keychain.get(k) : dflt; } catch (e) { return dflt; }
}
function settings() {
  return { host: kcGet(KC.host, DEFAULTS.host), user: kcGet(KC.user, DEFAULTS.user), pass: kcGet(KC.pass, null) };
}

async function askSettings(first) {
  const s = settings();
  const a = new Alert();
  a.title = first ? "Connect to your Pure box" : "Settings";
  a.message = "The password is stored in your iPhone Keychain. It is only sent to the Pure box, hashed.";
  a.addTextField("Router address", s.host);
  a.addTextField("Username", s.user);
  a.addSecureTextField(s.pass ? "Password (leave blank to keep)" : "Password", "");
  a.addAction("Save");
  if (!first) a.addDestructiveAction("Clear history");
  a.addCancelAction("Cancel");
  const i = await a.presentAlert();
  if (i === -1) return false;
  if (!first && i === 1) {
    const st = loadStore();
    st.samples = []; st.events = []; st.meta.last_reset_ts = null;
    saveStore(st);
    return true;
  }
  const host = a.textFieldValue(0).trim() || DEFAULTS.host;
  const user = a.textFieldValue(1).trim() || DEFAULTS.user;
  const pass = a.textFieldValue(2);
  Keychain.set(KC.host, host);
  Keychain.set(KC.user, user);
  if (pass) Keychain.set(KC.pass, pass);
  const st = loadStore();
  st.meta.auth_method = null; st.meta.fails = 0; st.meta.next_try = 0;
  saveStore(st);
  return !!(pass || s.pass);
}

// ---------------------------------------------------------------- storage

const FM = FileManager.local();
const STORE = FM.joinPath(FM.documentsDirectory(), "line-monitor-data.json");

function loadStore() {
  try {
    if (FM.fileExists(STORE)) {
      const s = JSON.parse(FM.readString(STORE));
      s.meta = s.meta || {};
      s.samples = s.samples || [];
      s.events = s.events || [];
      return s;
    }
  } catch (e) { /* start fresh */ }
  return { samples: [], events: [], meta: {} };
}

function saveStore(st) {
  const cutoff = Date.now() / 1000 - KEEP_DAYS * 86400;
  st.samples = st.samples.filter((x) => x.ts >= cutoff).slice(-MAX_SAMPLES);
  st.events = st.events.filter((x) => x.ts >= cutoff - 86400);
  FM.writeString(STORE, JSON.stringify(st));
}

function addEvent(st, ts, kind, source, text) {
  ts = Math.round(ts);
  if (st.events.some((e) => e.kind === kind && Math.abs(e.ts - ts) <= 20)) return;
  st.events.push({ ts, kind, source, text });
}

// ---------------------------------------------------------------- Sagemcom JSON-req client

const API = "/cgi/json-req";
const OK = ["XMO_REQUEST_NO_ERR", "Ok"];

class BoxError extends Error {
  constructor(code, msg) { super(msg || code); this.code = code; }
}

function quoteXpath(x) {
  return encodeURIComponent(x).replace(/%2F/g, "/").replace(/%3D/g, "=").replace(/%5B/g, "[")
    .replace(/%5D/g, "]").replace(/%40/g, "@").replace(/%22/g, '"');
}

class Box {
  constructor(host, user, pass, method) {
    this.host = host; this.user = user; this.method = method;
    this.passHash = this.hash(pass);
    this.sessionId = 0; this.serverNonce = ""; this.requestId = -1;
  }
  hash(s) { return this.method === "SHA512" ? sha512(s) : md5(s); }

  async request(actions, priority = false) {
    this.requestId += 1;
    const cnonce = Math.floor(Math.random() * 500000);
    const cred = this.hash(`${this.user}:${this.serverNonce}:${this.passHash}`);
    const authKey = this.hash(`${cred}:${this.requestId}:${cnonce}:JSON:${API}`);
    const payload = { request: { id: this.requestId, "session-id": this.sessionId, priority, actions, cnonce, "auth-key": authKey } };
    const r = new Request(`http://${this.host}${API}`);
    r.method = "POST";
    r.timeoutInterval = 15;
    r.headers = { "Content-Type": "application/x-www-form-urlencoded" };
    r.body = "req=" + encodeURIComponent(JSON.stringify(payload));
    let text;
    try {
      text = await r.loadString();
    } catch (e) {
      throw new BoxError("UNREACHABLE", `Can't reach the Pure box at ${this.host}. Are you on home Wi-Fi?`);
    }
    const status = r.response && r.response.statusCode;
    if (status && status !== 200) throw new BoxError("HTTP" + status, `The Pure box returned HTTP ${status}.`);
    let json;
    try { json = JSON.parse(text); } catch (e) { throw new BoxError("BADREPLY", "The Pure box sent an unexpected reply."); }
    const top = json.reply && json.reply.error && json.reply.error.description;
    if (OK.includes(top)) return json;
    if (top === "XMO_REQUEST_ACTION_ERR") {
      for (const a of json.reply.actions || []) {
        const d = a.error && a.error.description;
        if (d && d !== "XMO_NO_ERR") throw new BoxError(d);
      }
      return json;
    }
    throw new BoxError(top || "UNKNOWN");
  }

  async login() {
    const action = { id: 0, method: "logIn", parameters: {
      user: this.user, persistent: true,
      "session-options": {
        nss: [{ name: "gtw", uri: "http://sagemcom.com/gateway-data" }],
        language: "ident",
        "context-flags": { "get-content-name": true, "local-time": true },
        "capability-depth": 2,
        "capability-flags": { name: true, "default-value": false, restriction: true, description: false },
        "time-format": "ISO_8601",
        "write-only-string": "_XMO_WRITE_ONLY_",
        "undefined-write-only-string": "_XMO_UNDEFINED_WRITE_ONLY_",
      },
    } };
    const json = await this.request([action], true);
    const p = json.reply.actions[0].callbacks[0].parameters;
    if (p.id === undefined || p.id === null || !p.nonce) throw new BoxError("XMO_AUTHENTICATION_ERR");
    this.sessionId = p.id;
    this.serverNonce = String(p.nonce);
  }

  async getValue(xpath) {
    const json = await this.request([{ id: 0, method: "getValue", xpath: quoteXpath(xpath), options: {} }]);
    const cb = json.reply.actions[0].callbacks[0];
    return cb && cb.parameters ? cb.parameters.value : null;
  }

  async logout() {
    try { await this.request([{ id: 0, method: "logOut" }]); } catch (e) { /* session ends anyway */ }
  }
}

const AUTH_ERRORS = ["XMO_AUTHENTICATION_ERR", "XMO_ACCESS_RESTRICTION_ERR"];

async function loginBox(cfg, st) {
  const methods = st.meta.auth_method ? [st.meta.auth_method] : ["MD5", "SHA512"];
  let last;
  for (const m of methods) {
    const box = new Box(cfg.host, cfg.user, cfg.pass, m);
    try {
      await box.login();
      st.meta.auth_method = m;
      return box;
    } catch (e) {
      last = e;
      if (!AUTH_ERRORS.includes(e.code)) throw e; // network/500: don't keep trying
    }
  }
  if (st.meta.auth_method) st.meta.auth_method = null; // try detection again next time
  throw last;
}

// ---------------------------------------------------------------- parsing (same rules as the NAS app)

const norm = (k) => String(k).toLowerCase().replace(/[^a-z0-9]/g, "");

function walk(obj, path, out) {
  if (Array.isArray(obj)) obj.forEach((v, i) => walk(v, `${path}[${i}]`, out));
  else if (obj && typeof obj === "object") {
    for (const [k, v] of Object.entries(obj)) {
      if (v && typeof v === "object") walk(v, `${path}/${k}`, out);
      else out.push([`${path}/${k}`, k, v]);
    }
  }
  return out;
}

function find(obj, names, prefer) {
  const wanted = names.map(norm);
  let hits = walk(obj, "", []).filter(([, k, v]) => wanted.includes(norm(k)) && v !== null && v !== "")
    .map(([p, k, v]) => [wanted.indexOf(norm(k)), p, v]);
  if (!hits.length) return null;
  if (prefer) {
    const pref = hits.filter((h) => h[1].toLowerCase().includes(prefer));
    if (pref.length) hits = pref;
  }
  hits.sort((a, b) => a[0] - b[0]);
  return hits[0][2];
}

function container(tree, name) {
  if (Array.isArray(tree)) { for (const v of tree) { const r = container(v, name); if (r) return r; } }
  else if (tree && typeof tree === "object") {
    for (const [k, v] of Object.entries(tree)) if (norm(k) === name) return v;
    for (const v of Object.values(tree)) { const r = container(v, name); if (r) return r; }
  }
  return null;
}

function first(obj) {
  if (Array.isArray(obj)) return obj.length ? obj[0] : {};
  if (obj && typeof obj === "object") {
    const vals = Object.values(obj);
    if (vals.length === 1 && vals[0] && typeof vals[0] === "object") return first(vals[0]);
  }
  return obj || {};
}

function n(v) {
  if (v === null || v === undefined) return null;
  const x = parseFloat(String(v).trim().split(/\s+/)[0]);
  return Number.isFinite(x) ? x : null;
}
function dB(v) {
  let x = n(v);
  if (x === null) return null;
  if (Number.isInteger(x) && Math.abs(x) > 70) x /= 10; // tenths of a dB
  return Math.round(x * 10) / 10;
}
function mbps(v) {
  let x = n(v);
  if (x === null) return null;
  if (x > 5000000) x /= 1000;
  return Math.round(x / 100) / 10;
}

function parseDsl(tree, now) {
  const line = first(container(tree, "lines") || tree);
  const chan = first(container(tree, "channels") || tree);
  const s = { ts: now };
  const st = find(line, ["status", "link_status"]);
  s.status = st === null ? null : String(st);
  s.ds_rate = mbps(find(chan, ["downstream_curr_rate", "downstream_current_rate"])) ?? mbps(find(line, ["downstream_curr_rate"]));
  s.us_rate = mbps(find(chan, ["upstream_curr_rate", "upstream_current_rate"])) ?? mbps(find(line, ["upstream_curr_rate"]));
  s.ds_max = mbps(find(line, ["downstream_max_bit_rate", "downstream_max_rate", "downstream_attainable_rate"]));
  s.us_max = mbps(find(line, ["upstream_max_bit_rate", "upstream_max_rate", "upstream_attainable_rate"]));
  s.ds_att = dB(find(line, ["downstream_attenuation", "downstream_line_attenuation"]));
  s.us_att = dB(find(line, ["upstream_attenuation", "upstream_line_attenuation"]));
  s.ds_nm = dB(find(line, ["downstream_noise_margin", "downstream_snr_margin"]));
  s.us_nm = dB(find(line, ["upstream_noise_margin", "upstream_snr_margin"]));
  let up = n(find(line, ["showtime_start"], "stats"));
  if (up === null) up = n(find(line, ["last_change", "uptime"]));
  s.uptime_s = up !== null && up >= 0 ? Math.round(up) : null;
  s.reset_ts = s.uptime_s !== null ? Math.round(now - s.uptime_s) : null;
  return s;
}

const isUp = (s) => /^(up|showtime|connected)$/i.test(s.status || "");

// ---------------------------------------------------------------- one gentle read

async function readBox(cfg, st, manual) {
  const now = Date.now() / 1000;
  const m = st.meta;
  if (m.last_try && now - m.last_try < MIN_READ_GAP) return "skipped";
  if (m.fails && m.next_try && now < m.next_try) return "backoff";
  m.last_try = now;
  let box;
  try {
    box = await loginBox(cfg, st);
    if (!m.model) {
      try {
        const di = await box.getValue("Device/DeviceInfo/ModelName");
        if (di) m.model = String(di);
      } catch (e) { m.model = m.model || null; }
    }
    const tree = await box.getValue("Device/DSL");
    const s = parseDsl(tree, Date.now() / 1000);
    record(st, s);
    m.fails = 0; m.next_try = 0; m.error = null; m.last_ok = s.ts;
    return "ok";
  } catch (e) {
    m.fails = (m.fails || 0) + 1;
    m.next_try = now + BACKOFF[Math.min(m.fails, BACKOFF.length) - 1];
    m.error = friendly(e, cfg);
    return "error";
  } finally {
    if (box) await box.logout(); // never leave a session open on the box
  }
}

function record(st, s) {
  const m = st.meta;
  if (s.reset_ts) {
    if (m.last_reset_ts && s.reset_ts - m.last_reset_ts > RESYNC_GAP) {
      addEvent(st, s.reset_ts, "resync", "poll", "Line re-synced (seen by the app)");
    }
    m.last_reset_ts = s.reset_ts;
  }
  if (!isUp(s) && m.was_up !== false) addEvent(st, s.ts, "down", "poll", `Line status: ${s.status}`);
  m.was_up = isUp(s);
  st.samples.push(s);
}

function friendly(e, cfg) {
  const c = e.code || "";
  if (c === "UNREACHABLE") return e.message;
  if (AUTH_ERRORS.includes(c)) return "Login to the Pure box failed. Check the password in Settings.";
  if (c === "XMO_LOGIN_RETRY_ERR") return "The Pure box has locked logins after too many attempts.";
  if (c === "XMO_MAX_SESSION_COUNT_ERR") return "The Pure box has too many open sessions. Log out of its web page.";
  if (c.startsWith("HTTP5")) return "The Pure box's web interface returned an error.";
  return `Pure box error: ${e.message || c}`;
}

// ---------------------------------------------------------------- data for the dashboard

function view(st, cfg) {
  const now = Date.now() / 1000;
  const downs = st.events.filter((e) => e.kind === "down").sort((a, b) => a.ts - b.ts);
  const resyncs = st.events.filter((e) => e.kind === "resync").sort((a, b) => a.ts - b.ts);
  const used = new Set();
  const drops = [];
  for (const d of downs) {
    const r = resyncs.find((x) => !used.has(x) && x.ts > d.ts && x.ts <= d.ts + 600);
    if (r) used.add(r);
    drops.push({ down_ts: d.ts, up_ts: r ? r.ts : null, duration_s: r ? r.ts - d.ts : null, source: d.source, text: d.text });
  }
  for (const r of resyncs) if (!used.has(r)) drops.push({ down_ts: null, up_ts: r.ts, duration_s: null, source: r.source, text: r.text });
  drops.sort((a, b) => (b.down_ts || b.up_ts) - (a.down_ts || a.up_ts));
  const t = (o) => o.down_ts || o.up_ts;
  const m = st.meta;
  let error = m.error || null;
  if (error && m.fails && m.next_try > now) error += ` Trying again after ${new Date(m.next_try * 1000).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}.`;
  return {
    now,
    tz: null,
    poll_seconds: null,
    router: {
      host: cfg.host, info: { model_name: m.model || "Pure Telecom" },
      ok: m.error ? false : (m.last_ok ? true : null), error, retry_in: null,
      last_ok_ts: m.last_ok || null, last_try_ts: m.last_try || null, last_log_ts: null, log_error: null,
    },
    current: st.samples.length ? st.samples[st.samples.length - 1] : null,
    history: thin(st.samples, 600),
    drops: drops.filter((o) => t(o) >= now - 30 * 86400),
    counts: {
      h24: drops.filter((o) => t(o) >= now - 86400).length,
      d7: drops.filter((o) => t(o) >= now - 7 * 86400).length,
      d30: drops.filter((o) => t(o) >= now - 30 * 86400).length,
    },
    range: "30d",
  };
}

function thin(arr, max) {
  if (arr.length <= max) return arr;
  const step = arr.length / max;
  const out = [];
  for (let i = 0; i < max; i++) out.push(arr[Math.floor(i * step)]);
  out.push(arr[arr.length - 1]);
  return out;
}

// ---------------------------------------------------------------- dashboard (WebView)

const CSS = ":root {\n  --bg: #0b0f17;\n  --bg2: #111827;\n  --card: rgba(255, 255, 255, 0.045);\n  --card-b: rgba(255, 255, 255, 0.08);\n  --text: #eef2f7;\n  --muted: #8a94a6;\n  --faint: rgba(255, 255, 255, 0.07);\n  --accent: #38bdf8;\n  --accent2: #818cf8;\n  --good: #34d399;\n  --warn: #fbbf24;\n  --bad: #f87171;\n  --radius: 20px;\n  color-scheme: dark;\n}\n@media (prefers-color-scheme: light) {\n  :root {\n    --bg: #f2f4f8; --bg2: #e8ecf3; --card: #ffffff; --card-b: rgba(15, 23, 42, 0.07);\n    --text: #0f172a; --muted: #64748b; --faint: rgba(15, 23, 42, 0.07);\n    --accent: #0284c7; --accent2: #6366f1; --good: #059669; --warn: #d97706; --bad: #dc2626;\n    color-scheme: light;\n  }\n}\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody {\n  background: radial-gradient(1200px 600px at 80% -10%, rgba(56, 189, 248, .14), transparent 60%),\n              radial-gradient(900px 500px at -10% 10%, rgba(129, 140, 248, .12), transparent 60%),\n              var(--bg);\n  background-attachment: fixed;\n  color: var(--text);\n  font: 15px/1.4 -apple-system, BlinkMacSystemFont, \"SF Pro Text\", \"Inter\", \"Segoe UI\", Roboto, sans-serif;\n  -webkit-font-smoothing: antialiased;\n  -webkit-tap-highlight-color: transparent;\n  min-height: 100vh;\n}\nmain {\n  max-width: 640px; margin: 0 auto;\n  padding: calc(env(safe-area-inset-top) + 18px) 16px calc(env(safe-area-inset-bottom) + 110px);\n}\nh1 { font-size: 30px; letter-spacing: -0.02em; margin: 0; font-weight: 750; }\nh2 { font-size: 17px; margin: 0; font-weight: 650; }\n.sub { margin: 2px 0 0; color: var(--muted); font-size: 13px; }\n.top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }\n\n.pill {\n  display: inline-flex; align-items: center; gap: 7px; padding: 7px 12px; border-radius: 999px;\n  background: var(--card); border: 1px solid var(--card-b); font-size: 13px; white-space: nowrap;\n}\n.pill i { width: 8px; height: 8px; border-radius: 50%; background: var(--muted); }\n.pill.ok i { background: var(--good); box-shadow: 0 0 0 4px rgba(52, 211, 153, .18); }\n.pill.bad i { background: var(--bad); box-shadow: 0 0 0 4px rgba(248, 113, 113, .2); }\n.pill.warn i { background: var(--warn); }\n\n.banner {\n  background: rgba(248, 113, 113, .12); border: 1px solid rgba(248, 113, 113, .35);\n  color: var(--text); padding: 12px 14px; border-radius: 14px; margin-bottom: 14px; font-size: 14px;\n}\n.banner.warn { background: rgba(251, 191, 36, .1); border-color: rgba(251, 191, 36, .35); }\n\n.card {\n  background: var(--card); border: 1px solid var(--card-b); border-radius: var(--radius);\n  padding: 16px; margin-bottom: 12px;\n  backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);\n}\n.label { color: var(--muted); font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: .06em; }\n.hint { color: var(--muted); font-size: 13px; margin-top: 4px; }\n.unit { color: var(--muted); font-size: 15px; font-weight: 500; margin-left: 4px; }\n\n.hero { padding: 18px; }\n.speeds { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; margin: 10px 0 14px; }\n.speed.up { text-align: right; }\n.mini { color: var(--muted); font-size: 13px; font-weight: 600; margin-bottom: 2px; }\n.big { font-size: 50px; font-weight: 750; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; line-height: 1; }\n.mid { font-size: 30px; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; line-height: 1; }\n.arrow { font-size: 15px; font-weight: 800; margin-right: 5px; }\n.arrow.down { color: var(--accent); }\n.arrow.up { color: var(--accent2); }\n.bar { height: 8px; border-radius: 99px; background: var(--faint); overflow: hidden; }\n.bar span {\n  display: block; height: 100%; width: 0; border-radius: 99px;\n  background: linear-gradient(90deg, var(--accent), var(--accent2)); transition: width .6s ease;\n}\n\n.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 12px; }\n.grid .card { margin: 0; }\n.stat .value { font-size: 30px; font-weight: 720; letter-spacing: -0.02em; margin-top: 6px; font-variant-numeric: tabular-nums; }\n.chip {\n  display: inline-block; margin-top: 6px; padding: 3px 9px; border-radius: 999px; font-size: 12px; font-weight: 650;\n  background: var(--faint); color: var(--muted);\n}\n.chip.good { background: rgba(52, 211, 153, .15); color: var(--good); }\n.chip.warn { background: rgba(251, 191, 36, .15); color: var(--warn); }\n.chip.bad { background: rgba(248, 113, 113, .15); color: var(--bad); }\n#drops-24.bad { color: var(--bad); }\n#drops-24.good { color: var(--good); }\n\n.row { display: flex; align-items: center; gap: 8px; }\n.between { justify-content: space-between; flex-wrap: wrap; row-gap: 8px; }\n.seg { display: inline-flex; background: var(--faint); border-radius: 11px; padding: 3px; }\n.seg button {\n  appearance: none; border: 0; background: none; color: var(--muted); font: inherit; font-size: 13px; font-weight: 600;\n  padding: 6px 8px; border-radius: 8px; cursor: pointer;\n}\n.seg button.on { background: var(--card); color: var(--text); box-shadow: 0 1px 3px rgba(0, 0, 0, .25); }\n@media (prefers-color-scheme: light) { .seg button.on { background: #fff; } }\n.seg.small button { padding: 6px 7px; }\n\n.legend { display: flex; gap: 14px; margin: 12px 2px 4px; font-size: 12px; color: var(--muted); }\n.legend span::before {\n  content: \"\"; display: inline-block; width: 10px; height: 3px; border-radius: 2px; margin-right: 6px; vertical-align: middle;\n  background: var(--accent);\n}\n.legend .s2::before { background: var(--accent2); }\n.legend .s3::before { background: var(--bad); width: 7px; height: 7px; border-radius: 50%; }\n.chart { height: 200px; margin-top: 4px; }\n.chart svg { width: 100%; height: 100%; display: block; overflow: visible; }\n.chart .grid-line { stroke: var(--faint); stroke-width: 1; }\n.chart .axis { fill: var(--muted); font-size: 10px; }\n.chart .l1 { fill: none; stroke: var(--accent); stroke-width: 2.2; stroke-linejoin: round; stroke-linecap: round; }\n.chart .l2 { fill: none; stroke: var(--accent2); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; opacity: .9; }\n.chart .area { fill: url(#fade); }\n.chart .drop { fill: var(--bad); }\n.chart .drop-line { stroke: var(--bad); stroke-width: 1; opacity: .35; }\n.empty { color: var(--muted); font-size: 14px; padding: 18px 0 6px; text-align: center; }\n\n.day { margin-top: 14px; }\n.day-h { display: flex; justify-content: space-between; color: var(--muted); font-size: 12px; font-weight: 650;\n  text-transform: uppercase; letter-spacing: .05em; padding-bottom: 6px; border-bottom: 1px solid var(--faint); }\n.drop-row { display: flex; align-items: center; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--faint); }\n.drop-row:last-child { border-bottom: 0; }\n.dot { width: 9px; height: 9px; border-radius: 50%; background: var(--bad); flex: none; }\n.dot.resync { background: var(--warn); }\n.drop-time { font-weight: 650; font-variant-numeric: tabular-nums; font-size: 16px; min-width: 52px; }\n.drop-detail { color: var(--muted); font-size: 13px; flex: 1; }\n.src { font-size: 11px; color: var(--muted); background: var(--faint); padding: 2px 7px; border-radius: 6px; }\n\nfooter { color: var(--muted); font-size: 12px; text-align: center; margin-top: 18px; line-height: 1.6; }\n.settings-link { display: inline-block; margin-top: 8px; color: var(--accent); text-decoration: none; font-weight: 600; font-size: 14px; }\n\n.fab {\n  position: fixed; left: 50%; transform: translateX(-50%);\n  bottom: calc(env(safe-area-inset-bottom) + 18px);\n  display: inline-flex; align-items: center; gap: 8px;\n  border: 0; border-radius: 999px; padding: 14px 26px; font: inherit; font-weight: 700; font-size: 16px;\n  color: #fff; background: linear-gradient(135deg, var(--accent), var(--accent2));\n  box-shadow: 0 10px 30px rgba(56, 189, 248, .35), 0 2px 6px rgba(0, 0, 0, .3); cursor: pointer;\n}\n.fab:active { transform: translateX(-50%) scale(.97); }\n.fab.busy svg { animation: spin .9s linear infinite; }\n.fab.busy { opacity: .85; }\n@keyframes spin { to { transform: rotate(360deg); } }\n\n@media (max-width: 360px) {\n  .big { font-size: 42px; }\n  .mid { font-size: 26px; }\n  .stat .value { font-size: 26px; }\n}\n";
const APPJS = "\"use strict\";\n\nconst $ = (id) => document.getElementById(id);\nconst state = { data: null, metric: \"att\", range: \"24h\", busy: false };\n// EMBED: running inside the iPhone-only Scriptable app; data comes from the script, not /api\nconst EMBED = !!window.LM_EMBED;\nconst SPAN = { \"24h\": 86400, \"7d\": 7 * 86400, \"30d\": 30 * 86400 };\nconst inRange = (ts) => ts >= (state.data ? state.data.now : Date.now() / 1000) - SPAN[state.range];\n\n// ------------------------------------------------------------ formatting\nconst tz = () => (state.data && state.data.tz) || undefined;\nconst fmt = (opts) => new Intl.DateTimeFormat(\"en-IE\", { timeZone: tz(), ...opts });\nconst timeOf = (ts) => fmt({ hour: \"2-digit\", minute: \"2-digit\" }).format(ts * 1000);\nconst dayOf = (ts) => fmt({ weekday: \"short\", day: \"numeric\", month: \"short\" }).format(ts * 1000);\nconst dayKey = (ts) => fmt({ year: \"numeric\", month: \"2-digit\", day: \"2-digit\" }).format(ts * 1000);\nconst num = (v, d = 1) => (v === null || v === undefined ? \"\u2013\" : Number(v).toFixed(d));\n\nfunction duration(s) {\n  if (s === null || s === undefined) return \"\u2013\";\n  s = Math.max(0, Math.round(s));\n  const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60);\n  if (d) return `${d}d ${h}h`;\n  if (h) return `${h}h ${m}m`;\n  if (m) return `${m}m ${s % 60}s`;\n  return `${s}s`;\n}\n\nfunction ago(ts) {\n  const s = Date.now() / 1000 - ts;\n  if (s < 45) return \"just now\";\n  if (s < 3600) return `${Math.round(s / 60)} min ago`;\n  return `${timeOf(ts)}, ${dayOf(ts)}`;\n}\n\nfunction attQuality(v) {\n  if (v === null || v === undefined) return [\"\u2013\", \"\"];\n  if (v <= 20) return [\"Excellent\", \"good\"];\n  if (v <= 30) return [\"Good\", \"good\"];\n  if (v <= 40) return [\"Fair\", \"warn\"];\n  return [\"Poor\", \"bad\"];\n}\n\nfunction nmQuality(v) {\n  if (v === null || v === undefined) return [\"\u2013\", \"\"];\n  if (v >= 10) return [\"Excellent\", \"good\"];\n  if (v >= 6) return [\"Good\", \"good\"];\n  if (v >= 3) return [\"Marginal\", \"warn\"];\n  return [\"Poor\", \"bad\"];\n}\n\nfunction setChip(el, [text, cls]) {\n  el.textContent = text;\n  el.className = \"chip \" + cls;\n}\n\n// ------------------------------------------------------------ data\nasync function load(refresh = false) {\n  if (EMBED) {\n    if (!refresh) { if (state.data) render(); return; }\n    if (state.busy) return;\n    state.busy = true;\n    $(\"refresh\").classList.add(\"busy\");\n    send(\"refresh\");\n    return;\n  }\n  if (state.busy) return;\n  state.busy = true;\n  const btn = $(\"refresh\");\n  if (refresh) btn.classList.add(\"busy\");\n  try {\n    const url = (refresh ? \"/api/refresh\" : \"/api/status\") + \"?range=\" + state.range;\n    const res = await fetch(url, { method: refresh ? \"POST\" : \"GET\", cache: \"no-store\" });\n    if (!res.ok) throw new Error(`Server returned ${res.status}`);\n    state.data = await res.json();\n    render();\n  } catch (e) {\n    showBanner(`Can't reach the monitor: ${e.message}`, \"bad\");\n    setPill(\"bad\", \"Offline\");\n  } finally {\n    state.busy = false;\n    btn.classList.remove(\"busy\");\n  }\n}\n\n// ---- bridge to the Scriptable app (EMBED only)\nlet bridgeCb = null, pending = null;\nfunction send(action) {\n  if (bridgeCb) { const cb = bridgeCb; bridgeCb = null; cb(action); } else { pending = action; }\n}\nwindow.LM_wait = (cb) => {\n  if (pending) { const a = pending; pending = null; cb(a); } else { bridgeCb = cb; }\n};\nwindow.LM_render = (data) => {\n  state.data = data;\n  state.busy = false;\n  $(\"refresh\").classList.remove(\"busy\");\n  render();\n};\n\nfunction showBanner(text, kind) {\n  const b = $(\"banner\");\n  if (!text) { b.hidden = true; return; }\n  b.hidden = false;\n  b.className = \"banner \" + (kind || \"\");\n  b.textContent = text;\n}\n\nfunction setPill(cls, text) {\n  $(\"pill\").className = \"pill \" + cls;\n  $(\"pill-text\").textContent = text;\n}\n\n// ------------------------------------------------------------ render\nfunction render() {\n  const d = state.data;\n  const c = d.current;\n  const r = d.router;\n\n  if (r.ok === false) {\n    const retry = r.retry_in ? ` Next try in ${Math.round(r.retry_in / 60)} min.` : \"\";\n    showBanner(r.error + retry + (c ? \" Showing the last reading.\" : \"\"), \"bad\");\n    setPill(\"bad\", \"Router error\");\n  } else if (r.log_error) {\n    showBanner(r.log_error + \" Drops are still detected from the line's sync time.\", \"warn\");\n  } else {\n    showBanner(\"\");\n  }\n\n  if (c) {\n    const up = /^(up|showtime|connected)$/i.test(c.status || \"\");\n    if (r.ok !== false) setPill(up ? \"ok\" : \"bad\", up ? \"Line up\" : `Line ${c.status || \"down\"}`);\n    $(\"ds-rate\").textContent = num(c.ds_rate);\n    $(\"us-rate\").textContent = num(c.us_rate);\n    const pct = c.ds_max ? Math.min(100, (100 * c.ds_rate) / c.ds_max) : 0;\n    $(\"ds-bar\").style.width = pct + \"%\";\n    $(\"max-text\").textContent = c.ds_max\n      ? `Line maximum ${num(c.ds_max)} \u2193 / ${num(c.us_max)} \u2191 Mbps \u00b7 using ${Math.round(pct)}%`\n      : \"Line maximum \u2013\";\n    $(\"ds-att\").textContent = num(c.ds_att);\n    setChip($(\"att-chip\"), attQuality(c.ds_att));\n    $(\"us-att\").textContent = c.us_att ? `Up ${num(c.us_att)} dB` : \"Up not reported\";\n    $(\"ds-nm\").textContent = num(c.ds_nm);\n    setChip($(\"nm-chip\"), nmQuality(Math.min(c.ds_nm ?? 99, c.us_nm ?? 99)));\n    $(\"us-nm\").textContent = `Up ${num(c.us_nm)} dB`;\n    const live = c.reset_ts ? d.now - c.reset_ts : c.uptime_s;\n    $(\"uptime\").textContent = up ? duration(live) : \"Down\";\n    $(\"reset-at\").textContent = c.reset_ts ? `Last reset ${timeOf(c.reset_ts)}, ${dayOf(c.reset_ts)}` : \"Last reset \u2013\";\n  } else if (r.ok !== false) {\n    setPill(\"warn\", \"Waiting\");\n  }\n\n  const n24 = d.counts.h24;\n  $(\"drops-24\").textContent = n24;\n  $(\"drops-24\").className = n24 ? \"bad\" : \"good\";\n  $(\"drops-7\").textContent = `7 days ${d.counts.d7} \u00b7 30 days ${d.counts.d30}`;\n\n  const info = r.info || {};\n  $(\"sub\").textContent = [info.model_name || \"Pure Telecom\", \"VDSL2\", r.host].filter(Boolean).join(\" \u00b7 \");\n  const auto = d.poll_seconds ? ` \u00b7 auto every ${Math.round(d.poll_seconds / 60)} min` : \"\";\n  $(\"updated\").textContent = r.last_ok_ts ? `Updated ${ago(r.last_ok_ts)}${auto}` : \"Not read yet\";\n  $(\"device\").textContent = [info.software_version && `Firmware ${info.software_version}`,\n    r.last_log_ts && `router log read ${ago(r.last_log_ts)}`].filter(Boolean).join(\" \u00b7 \");\n\n  renderChart();\n  renderDrops();\n}\n\nfunction renderDrops() {\n  const d = state.data;\n  const box = $(\"drops\");\n  const label = { \"24h\": \"last 24 hours\", \"7d\": \"last 7 days\", \"30d\": \"last 30 days\" }[state.range];\n  $(\"drops-range\").textContent = label;\n  box.replaceChildren();\n  const drops = d.drops.filter((o) => inRange(o.down_ts || o.up_ts));\n  if (!drops.length) {\n    const e = document.createElement(\"div\");\n    e.className = \"empty\";\n    e.textContent = `No drops in the ${label} \ud83c\udf89`;\n    box.append(e);\n    return;\n  }\n  const groups = new Map();\n  for (const o of drops) {\n    const t = o.down_ts || o.up_ts;\n    const k = dayKey(t);\n    if (!groups.has(k)) groups.set(k, { t, items: [] });\n    groups.get(k).items.push(o);\n  }\n  for (const { t, items } of groups.values()) {\n    const g = document.createElement(\"div\");\n    g.className = \"day\";\n    const h = document.createElement(\"div\");\n    h.className = \"day-h\";\n    h.append(span(dayOf(t)), span(`${items.length} ${items.length === 1 ? \"drop\" : \"drops\"}`));\n    g.append(h);\n    for (const o of items) {\n      const row = document.createElement(\"div\");\n      row.className = \"drop-row\";\n      const dot = document.createElement(\"span\");\n      dot.className = \"dot\" + (o.down_ts ? \"\" : \" resync\");\n      const detail = o.down_ts\n        ? (o.up_ts ? `Back at ${timeOf(o.up_ts)} \u00b7 offline ${duration(o.duration_s)}` : \"Line went down\")\n        : \"Line dropped and re-synced\";\n      row.append(dot, span(timeOf(o.down_ts || o.up_ts), \"drop-time\"), span(detail, \"drop-detail\"),\n        span(o.source === \"log\" ? \"router log\" : \"monitor\", \"src\"));\n      row.title = o.text || \"\";\n      g.append(row);\n    }\n    box.append(g);\n  }\n}\n\nfunction span(text, cls) {\n  const s = document.createElement(\"span\");\n  s.textContent = text;\n  if (cls) s.className = cls;\n  return s;\n}\n\n// ------------------------------------------------------------ chart\nconst SVGNS = \"http://www.w3.org/2000/svg\";\nconst el = (name, attrs = {}) => {\n  const n = document.createElementNS(SVGNS, name);\n  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);\n  return n;\n};\n\nconst METRICS = {\n  att: { keys: [\"ds_att\", \"us_att\"], names: [\"Down\", \"Up\"], unit: \"dB\" },\n  rate: { keys: [\"ds_rate\", \"us_rate\"], names: [\"Down\", \"Up\"], unit: \"Mbps\" },\n  nm: { keys: [\"ds_nm\", \"us_nm\"], names: [\"Down\", \"Up\"], unit: \"dB\" },\n};\n\nfunction renderChart() {\n  const d = state.data;\n  const m = METRICS[state.metric];\n  const box = $(\"chart\");\n  const legend = $(\"legend\");\n  legend.replaceChildren(span(`${m.names[0]} (${m.unit})`), span(`${m.names[1]}`, \"s2\"), span(\"Drop\", \"s3\"));\n  box.replaceChildren();\n\n  // VDSL modems often report upstream attenuation as 0 (\"not measured\"): treat it as missing.\n  const pts = d.history\n    .filter((p) => p[m.keys[0]] !== null && inRange(p.ts))\n    .map((p) => (state.metric === \"att\" && !p.us_att ? { ...p, us_att: null } : p));\n  if (pts.length < 2) {\n    const e = document.createElement(\"div\");\n    e.className = \"empty\";\n    e.textContent = \"The chart fills in as readings come in.\";\n    box.append(e);\n    return;\n  }\n\n  const W = box.clientWidth || 340, H = box.clientHeight || 200;\n  const L = 34, R = 6, T = 8, B = 22;\n  const span_ = SPAN[state.range];\n  const x0 = Math.max(pts[0].ts, d.now - span_), x1 = d.now;\n  const vals = pts.flatMap((p) => m.keys.map((k) => p[k])).filter((v) => v !== null);\n  let lo = Math.min(...vals), hi = Math.max(...vals);\n  const pad = Math.max(1, (hi - lo) * 0.15);\n  lo = Math.max(0, Math.floor(lo - pad)); hi = Math.ceil(hi + pad);\n  const X = (t) => L + ((t - x0) / Math.max(1, x1 - x0)) * (W - L - R);\n  const Y = (v) => T + (1 - (v - lo) / Math.max(1e-6, hi - lo)) * (H - T - B);\n\n  const svg = el(\"svg\", { viewBox: `0 0 ${W} ${H}`, preserveAspectRatio: \"none\" });\n  const defs = el(\"defs\");\n  const grad = el(\"linearGradient\", { id: \"fade\", x1: 0, y1: 0, x2: 0, y2: 1 });\n  grad.append(el(\"stop\", { offset: \"0%\", \"stop-color\": getCss(\"--accent\"), \"stop-opacity\": \"0.28\" }),\n    el(\"stop\", { offset: \"100%\", \"stop-color\": getCss(\"--accent\"), \"stop-opacity\": \"0\" }));\n  defs.append(grad);\n  svg.append(defs);\n\n  for (let i = 0; i <= 3; i++) {\n    const v = lo + ((hi - lo) * i) / 3;\n    const y = Y(v);\n    svg.append(el(\"line\", { x1: L, x2: W - R, y1: y, y2: y, class: \"grid-line\" }));\n    const t = el(\"text\", { x: L - 6, y: y + 3, \"text-anchor\": \"end\", class: \"axis\" });\n    t.textContent = v.toFixed(hi - lo < 6 ? 1 : 0);\n    svg.append(t);\n  }\n  const ticks = 4;\n  for (let i = 0; i <= ticks; i++) {\n    const ts = x0 + ((x1 - x0) * i) / ticks;\n    const t = el(\"text\", { x: X(ts), y: H - 5, \"text-anchor\": i === 0 ? \"start\" : i === ticks ? \"end\" : \"middle\", class: \"axis\" });\n    t.textContent = state.range === \"24h\" ? timeOf(ts) : fmt({ day: \"numeric\", month: \"short\" }).format(ts * 1000);\n    svg.append(t);\n  }\n\n  const path = (key) => {\n    let s = \"\", gap = true;\n    for (const p of pts) {\n      if (p[key] === null) { gap = true; continue; }\n      s += `${gap ? \"M\" : \"L\"}${X(p.ts).toFixed(1)},${Y(p[key]).toFixed(1)}`;\n      gap = false;\n    }\n    return s;\n  };\n  const p1 = path(m.keys[0]);\n  const first = pts[0], last = pts[pts.length - 1];\n  svg.append(el(\"path\", { d: `${p1}L${X(last.ts)},${H - B}L${X(first.ts)},${H - B}Z`, class: \"area\" }));\n  svg.append(el(\"path\", { d: path(m.keys[1]), class: \"l2\" }));\n  svg.append(el(\"path\", { d: p1, class: \"l1\" }));\n\n  for (const o of d.drops) {\n    const t = o.down_ts || o.up_ts;\n    if (t < x0) continue;\n    const x = X(t);\n    svg.append(el(\"line\", { x1: x, x2: x, y1: T, y2: H - B, class: \"drop-line\" }));\n    svg.append(el(\"circle\", { cx: x, cy: H - B, r: 3.5, class: \"drop\" }));\n  }\n  box.append(svg);\n}\n\nfunction getCss(name) {\n  return getComputedStyle(document.documentElement).getPropertyValue(name).trim() || \"#38bdf8\";\n}\n\n// ------------------------------------------------------------ events\nfunction wireSeg(id, attr, key, reload) {\n  $(id).addEventListener(\"click\", (e) => {\n    const b = e.target.closest(\"button\");\n    if (!b) return;\n    for (const x of $(id).querySelectorAll(\"button\")) x.classList.toggle(\"on\", x === b);\n    state[key] = b.dataset[attr];\n    if (reload) load(false);\n    else if (key === \"range\") { if (state.data) render(); }\n    else renderChart();\n  });\n}\n\ndocument.addEventListener(\"DOMContentLoaded\", () => {\n  wireSeg(\"metric-seg\", \"metric\", \"metric\", false);\n  wireSeg(\"range-seg\", \"range\", \"range\", !EMBED);\n  $(\"refresh\").addEventListener(\"click\", () => load(true));\n  if (EMBED) {\n    const s = document.createElement(\"a\");\n    s.href = \"#\";\n    s.className = \"settings-link\";\n    s.textContent = \"Settings\";\n    s.addEventListener(\"click\", (e) => { e.preventDefault(); send(\"settings\"); });\n    $(\"device\").after(s);\n    if (window.LM_DATA) { state.data = window.LM_DATA; render(); }\n  } else {\n    load(false);\n    setInterval(() => { if (!document.hidden) load(false); }, 60_000);\n    document.addEventListener(\"visibilitychange\", () => { if (!document.hidden) load(false); });\n  }\n  let w = window.innerWidth;\n  window.addEventListener(\"resize\", () => { if (window.innerWidth !== w && state.data) { w = window.innerWidth; renderChart(); } });\n});\n";
const BODY = "<main>\n  <header class=\"top\">\n    <div>\n      <h1>Line Monitor</h1>\n      <p class=\"sub\" id=\"sub\">Pure Telecom \u00b7 VDSL2</p>\n    </div>\n    <span class=\"pill\" id=\"pill\"><i></i><b id=\"pill-text\">Loading</b></span>\n  </header>\n\n  <div class=\"banner\" id=\"banner\" hidden></div>\n\n  <section class=\"card hero\">\n    <div class=\"label\">Sync speed</div>\n    <div class=\"speeds\">\n      <div class=\"speed\">\n        <div class=\"mini\"><span class=\"arrow down\" aria-hidden=\"true\">\u2193</span>Download</div>\n        <div><span class=\"big\" id=\"ds-rate\">\u2013</span><span class=\"unit\">Mbps</span></div>\n      </div>\n      <div class=\"speed up\">\n        <div class=\"mini\"><span class=\"arrow up\" aria-hidden=\"true\">\u2191</span>Upload</div>\n        <div><span class=\"mid\" id=\"us-rate\">\u2013</span><span class=\"unit\">Mbps</span></div>\n      </div>\n    </div>\n    <div class=\"bar\"><span id=\"ds-bar\"></span></div>\n    <div class=\"hint\" id=\"max-text\">Line maximum \u2013</div>\n  </section>\n\n  <section class=\"grid\">\n    <div class=\"card stat\">\n      <div class=\"label\">Attenuation \u2193</div>\n      <div class=\"value\"><span id=\"ds-att\">\u2013</span><span class=\"unit\">dB</span></div>\n      <div class=\"chip\" id=\"att-chip\">\u2013</div>\n      <div class=\"hint\" id=\"us-att\">Up \u2013</div>\n    </div>\n    <div class=\"card stat\">\n      <div class=\"label\">Noise margin</div>\n      <div class=\"value\"><span id=\"ds-nm\">\u2013</span><span class=\"unit\">dB \u2193</span></div>\n      <div class=\"chip\" id=\"nm-chip\">\u2013</div>\n      <div class=\"hint\" id=\"us-nm\">Up \u2013</div>\n    </div>\n    <div class=\"card stat\">\n      <div class=\"label\">Line up for</div>\n      <div class=\"value\"><span id=\"uptime\">\u2013</span></div>\n      <div class=\"hint\" id=\"reset-at\">Last reset \u2013</div>\n    </div>\n    <div class=\"card stat\">\n      <div class=\"label\">Drops \u00b7 24 h</div>\n      <div class=\"value\"><span id=\"drops-24\">\u2013</span></div>\n      <div class=\"hint\" id=\"drops-7\">7 days \u2013</div>\n    </div>\n  </section>\n\n  <section class=\"card\">\n    <div class=\"row between\">\n      <div class=\"seg\" id=\"metric-seg\" role=\"tablist\">\n        <button data-metric=\"att\" class=\"on\">Attenuation</button>\n        <button data-metric=\"rate\">Sync</button>\n        <button data-metric=\"nm\">Margin</button>\n      </div>\n      <div class=\"seg small\" id=\"range-seg\">\n        <button data-range=\"24h\" class=\"on\">24h</button>\n        <button data-range=\"7d\">7d</button>\n        <button data-range=\"30d\">30d</button>\n      </div>\n    </div>\n    <div class=\"legend\" id=\"legend\"></div>\n    <div class=\"chart\" id=\"chart\"></div>\n  </section>\n\n  <section class=\"card\">\n    <div class=\"row between\">\n      <h2>Line drops &amp; resets</h2>\n      <span class=\"hint\" id=\"drops-range\"></span>\n    </div>\n    <div id=\"drops\"></div>\n  </section>\n\n  <footer>\n    <div id=\"updated\">Not refreshed yet</div>\n    <div id=\"device\"></div>\n  </footer>\n</main>\n\n<button class=\"fab\" id=\"refresh\" aria-label=\"Refresh\">\n  <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" aria-hidden=\"true\"><path fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M20 11a8 8 0 1 0-2.3 5.7M20 5v6h-6\"/></svg>\n  <span>Refresh</span>\n</button>";

function page(data) {
  const safe = (o) => JSON.stringify(o).replace(/</g, "\\u003c");
  return `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<style>${CSS}</style></head><body>${BODY}
<script>window.LM_EMBED = true; window.LM_DATA = ${safe(data)};</script>
<script>${APPJS}</script></body></html>`;
}

async function runApp() {
  let cfg = settings();
  if (!cfg.pass) {
    if (!(await askSettings(true))) return;
    cfg = settings();
  }
  const st = loadStore();
  const wv = new WebView();
  await wv.loadHTML(page(view(st, cfg)));
  let open = true;
  const closed = wv.present(true).then(() => { open = false; });
  const push = async () => {
    try { await wv.evaluateJavaScript(`window.LM_render(${JSON.stringify(view(st, cfg))})`, false); } catch (e) { /* closed */ }
  };
  // Read the box once on open (respects the 1-minute gap and any backoff)
  await readBox(cfg, st, false);
  saveStore(st);
  await push();

  while (open) {
    const action = await Promise.race([wv.evaluateJavaScript("LM_wait(completion)", true), closed]);
    if (!open || !action) break;
    if (action === "refresh") {
      await readBox(cfg, st, true);
      saveStore(st);
      await push();
    } else if (action === "settings") {
      if (await askSettings(false)) {
        cfg = settings();
        Object.assign(st, loadStore());
        st.meta.last_try = 0;
        await readBox(cfg, st, true);
        saveStore(st);
      }
      await push();
    }
  }
}

// ---------------------------------------------------------------- home-screen widget

function fmtDur(s) {
  if (s === null || s === undefined) return "–";
  s = Math.max(0, Math.round(s));
  const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), mm = Math.floor((s % 3600) / 60);
  return d ? `${d}d ${h}h` : h ? `${h}h ${mm}m` : `${mm}m`;
}

async function runWidget() {
  const cfg = settings();
  const st = loadStore();
  if (cfg.pass) {
    await readBox(cfg, st, false);
    saveStore(st);
  }
  const v = view(st, cfg);
  const c = v.current;
  const fam = config.widgetFamily || "medium";
  const w = new ListWidget();
  w.refreshAfterDate = new Date(Date.now() + 15 * 60 * 1000);
  const accent = new Color("#38bdf8"), muted = new Color("#8a94a6"), bad = new Color("#f87171"), good = new Color("#34d399");

  if (fam.startsWith("accessory")) {
    const t = w.addText(c ? `↓${c.ds_rate ?? "–"} · ${c.ds_att ?? "–"} dB` : "Line –");
    t.font = Font.boldSystemFont(14);
    const t2 = w.addText(`Drops 24h: ${v.counts.h24}`);
    t2.font = Font.systemFont(12);
    Script.setWidget(w);
    return;
  }

  const g = new LinearGradient();
  g.colors = [new Color("#111827"), new Color("#0b0f17")];
  g.locations = [0, 1];
  w.backgroundGradient = g;
  w.setPadding(14, 16, 14, 16);

  const head = w.addStack();
  head.centerAlignContent();
  const dot = head.addText("●");
  const up = c && isUp(c) && v.router.ok !== false;
  dot.textColor = !c ? muted : up ? good : bad;
  dot.font = Font.systemFont(10);
  head.addSpacer(5);
  const title = head.addText(!cfg.pass ? "Tap to set up" : v.router.ok === false ? "Can't read box" : up ? "Line up" : c ? "Line down" : "No reading yet");
  title.font = Font.semiboldSystemFont(12);
  title.textColor = Color.white();
  head.addSpacer();
  if (v.router.last_ok_ts) {
    const when = head.addDate(new Date(v.router.last_ok_ts * 1000));
    when.applyTimeStyle();
    when.font = Font.systemFont(11);
    when.textColor = muted;
  }
  w.addSpacer(6);

  const big = w.addStack();
  big.bottomAlignContent();
  const ds = big.addText(c && c.ds_rate !== null ? c.ds_rate.toFixed(1) : "–");
  ds.font = Font.boldRoundedSystemFont(fam === "small" ? 30 : 34);
  ds.textColor = Color.white();
  big.addSpacer(4);
  const unit = big.addText("Mbps ↓");
  unit.font = Font.mediumSystemFont(12);
  unit.textColor = accent;
  w.addSpacer(6);

  const row = (label, value, color) => {
    const s = w.addStack();
    const l = s.addText(label);
    l.font = Font.systemFont(12);
    l.textColor = muted;
    s.addSpacer();
    const r = s.addText(value);
    r.font = Font.semiboldSystemFont(12);
    r.textColor = color || Color.white();
  };
  row("Attenuation", c && c.ds_att !== null ? `${c.ds_att.toFixed(1)} dB` : "–");
  row("Drops 24h", String(v.counts.h24), v.counts.h24 ? bad : good);
  if (fam !== "small") {
    row("Up for", c && up ? fmtDur(v.now - c.reset_ts) : "–");
    row("Upload · margin", c ? `${c.us_rate ?? "–"} Mbps · ${c.ds_nm ?? "–"} dB` : "–");
  }
  Script.setWidget(w);
}

// ---------------------------------------------------------------- start

if (config.runsInWidget) {
  await runWidget();
} else {
  await runApp();
}
Script.complete();
